#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using HauntedFish.BossFight;
public static class BossBoundControllerRepair{
 public static void Run(Scene scene){var manager=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<BossArenaManager>(true)).Single();var ms=new SerializedObject(manager);var keep=new List<Component>();foreach(string field in new[]{"_Defenses","_DragInput","_Views","_Hud"}){var c=ms.FindProperty(field).objectReferenceValue as Component;if(!c)throw new Exception("Missing authoritative authored binding "+field);keep.Add(c);}var board=(BossDefenseBoard)keep[0];if(!board.ValidateAuthoredBindings(out var error))throw new Exception(error);for(int i=0;i<6;i++)keep.Add(board.Piece(i));var view=new SerializedObject(keep[2]);foreach(string field in new[]{"_GhostFraming","_Characters","_StormShadows","_Storm"}){var c=view.FindProperty(field).objectReferenceValue as Component;if(c)keep.Add(c);}var map=new Dictionary<UnityEngine.Object,UnityEngine.Object>();foreach(var c in keep)foreach(var duplicate in c.gameObject.GetComponents(c.GetType()).Where(x=>x!=c)){if(duplicate.gameObject!=c.gameObject)throw new Exception("Controller is not on identical authored object");map[duplicate]=c;}
 // Exact bound Boss component types only, identical GameObject; preserve every GameObject/Transform/body/art.
 foreach(var c in scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<MonoBehaviour>(true)).Where(c=>c&&!map.ContainsKey(c))){var s=new SerializedObject(c);var p=s.GetIterator();bool changed=false;while(p.Next(true))if(p.propertyType==SerializedPropertyType.ObjectReference&&p.objectReferenceValue&&map.TryGetValue(p.objectReferenceValue,out var replacement)){p.objectReferenceValue=replacement;changed=true;}if(changed){s.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.RecordPrefabInstancePropertyModifications(c);}}
 var lines=map.Select(x=>x.Key.name+" | "+x.Key.GetType().Name+" | retained direct arena/view/slot binding on same GameObject").ToArray();foreach(var duplicate in map.Keys)UnityEngine.Object.DestroyImmediate(duplicate);if(!board.ValidateAuthoredBindings(out error))throw new Exception(error);File.WriteAllLines("Tools/BossFightTests/Evidence/composition/bound-controller-repair.txt",lines);}
}
#endif
